        emote("\u{1F3C1} " + xLine("finish", mn, { x: String(h.done.length) }), mn);
        earnRibbons(mn, CFG.HUNT_RIBBONS + (h.done.length === 1 ? 1 : 0), h.done.length === 1 ? "first home in the hunt" : "finishin' the hunt");
