      L2.nest.eggs += n;
      bump1(L2.nest.by, mn, n);
      L2.nest.types = L2.nest.types || {};
      const mine = L2.nest.types[mn] = L2.nest.types[mn] || {};
      const tt = types && Object.keys(types).length ? types : { stud: n };
